{"function":"() => {
const out = {};
const q = s => [...document.querySelectorAll(s)];
out.content = q('.content').map(e => ({tag: e.tagName, cls: e.className, txt: e.textContent.trim().slice(0,60), bg: getComputedStyle(e).backgroundColor, color: getComputedStyle(e).color, parent: e.parentElement.className}));
out.pastel = q('.primary-pastel-01').map(e => ({tag: e.tagName, cls: e.className, txt: e.textContent.trim().slice(0,60), outer: e.outerHTML.slice(0,300)}));
out.filters = q('[class*=filter] *').filter(e=>getComputedStyle(e).cursor==='pointer').slice(0,10).map(e=>({tag:e.tagName, cls:e.className, role:e.getAttribute('role'), tab:e.tabIndex, txt:e.textContent.trim().slice(0,30)}));
out.tabs = q('nav[aria-label="Abas de Navegação Simples"] button').map(b=>({txt:b.textContent.trim(), cls:b.className, parentCls:b.parentElement.className, ariaSel:b.getAttribute('aria-selected'), ariaCur:b.getAttribute('aria-current'), role:b.getAttribute('role')}));
out.h = q('h1,h2,h3,h4,h5,h6').map(h=>h.tagName+':'+h.textContent.trim());
out.eye = q('br-button[icon=eye]').slice(0,1).map(e=>e.outerHTML.slice(0,400));
out.dateInputs = q('br-input').map(e=>({outer:e.outerHTML.slice(0,300)}));
return out;
}"}

