const S4=st(['click aba "Concluídos" (#HISTORICO)','click botão olho da linha 1 (Pérola Veloz II, NAO COMPARECIMENTO)']);
const S6=st(['click botão olho da linha 1 (aba Tramitando)','click "Editar" em Dados da vistoria','click "Salvar"']);
const S8=st(['click chip "Cidade"','click opção "Barra Nova"']);
const S8b=st(['click chip "Cidade"']);
const S9=st(['click botão "Atribuir vistoriador" (user-plus) da linha 1']);
const S10=st(['click aba "Agendar"','click "Agendar" da linha 1']);
const S11=st(['click #avatar-dropdown-trigger']);
const S12=st(['click "Exportar Vistorias"']);
const F=[];
const add=(o)=>{F.push(o); return F.length-1;};
