i.eye=add({selector:'tbody br-button[icon="eye"]',rule:'wcag:4.1.2',observed:'Botões "visualizar" (ícone olho) das linhas: <button> interno com aria-label="" e só um ícone; nome acessível vazio (axe button-name).',expected:'Cada botão de visualizar com nome acessível (ex.: "Visualizar vistoria").',state:S1,evidence:['S-page-001','F-050','F-051','F-059','S-page-003','F-142']});
i.chips=add({selector:'pnip-filter-panel .col-auto > span.br-tag.interaction',rule:'wcag:2.1.1',references:['emag:2.1'],observed:'Filtros Cidade, Porto, Vistoriador e Status são <span class="br-tag interaction"> com cursor:pointer e listener de clique, tabIndex=-1, sem role; não entram na ordem de Tab (sequência vai de Concluídos direto para o campo de busca).',expected:'Filtros operáveis por teclado (button/aria-expanded ou br-select do DS).',state:S1,evidence:['S-page-001']});
i.opts=add({selector:'.br-list.d-block .br-item',rule:'wcag:4.1.2',references:['wcag:2.1.1'],observed:'Opções do filtro aberto (ex.: Cidade) são div.br-item > div.br-radio > <label> sem <input type="radio">, sem role, sem estado e não focáveis (tabIndex=-1).',expected:'Opções expostas como radio/option com estado de seleção e alcançáveis por teclado.',state:S8b,evidence:[]});
i.rmchip=add({selector:'pnip-filter-panel span.br-tag button.circle',rule:'wcag:4.1.2',observed:'Botão "×" que remove o filtro aplicado ("Barra Nova") só tem <i class="fas fa-times">, sem texto nem aria-label (axe button-name).',expected:'Botão com nome acessível (ex.: "Remover filtro Barra Nova").',state:S8,evidence:['S-page-006','F-195']});
i.tabs=add({selector:'.tab-item > button',rule:'govbr-3.7.0-accessibility-tab-86e80cffa071',references:['wcag:1.3.1'],observed:'A aba ativa só é indicada pela classe .tab-item.active (cor/sublinhado); os botões Agendar/Tramitando/Concluídos não têm aria-selected nem aria-current.',expected:'Estado da aba ativa exposto programaticamente (aria-selected="true"/"false" ou aria-current).',state:S1,evidence:['S-page-001']});
i.pag=add({selector:'nav[aria-label="Paginação de resultados"] a.page.active',rule:'wcag:1.3.1',observed:'Página atual "1" é indicada apenas visualmente (classe .active); <a href="javascript:void(0)"> sem aria-current.',expected:'Página atual com aria-current="page".',state:S1,evidence:['S-page-001']});
i.li=add({selector:'nav[aria-label="Paginação de resultados"] li > li',rule:'wcag:1.3.1',observed:'Cada número de página é um <li> aninhado diretamente em outro <li> (li > li > a), sem <ul>/<ol> pai (axe listitem).',expected:'Itens de lista com pai ul/ol válido.',state:S1,evidence:['S-page-001','F-086','F-087','F-088','F-089']});
i.tagBlue=add({selector:'pnip-status-solicitacao-utils .bg-blue-40 > .text-center',rule:'wcag:1.4.3',references:['emag:4.1'],observed:'Etiqueta de status "Vistoria agendada": texto #ffffff sobre #4f97d1, 14px normal = 3,14:1.',expected:'Contraste mínimo de 4,5:1.',state:S1,evidence:['S-page-001','
